import re

def trump_detector(text: str) -> float:
    text = text.lower()
    vowels = "aeiou"
    vowel_groups = []
    current_group = []

    for char in text:
        if char in vowels:
            current_group.append(char)
        else:
            if current_group:
                vowel_groups.append(current_group)
                current_group = []
    if current_group:
        vowel_groups.append(current_group)

    total_vowels = sum(len(group) for group in vowel_groups)
    extra_vowels = sum(max(0, len(group) - 1) for group in vowel_groups)

    return round(extra_vowels / total_vowels, 2)
